package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Read-only, bounded equivalents of the six legacy UI reads. Never produces a write manifest. */
public final class ReadDisplayTools {
    public static final Set<String> TYPES=Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList(
        "getRangeValue","getRangeFormulas","getMerges","getSelection","getFilter","createChart")));
    public static final String CONTRACT="只读工具 read_display {type,sheetId,...}：type 仅 getRangeValue/getRangeFormulas（明确 range）、getMerges、getSelection、getFilter、createChart。"
        +"值/公式/图表物化每次最多1000格，选区仅捕获坐标并沿用现有20万格有限范围上限；sheetId 必填；读取任务执行时的已保存版本，不写工作簿。getSelection 返回启动时捕获的选区，不是实时查询；没有捕获时需提问。"
        +"createChart 使用 chartType:bar/line/pie、categoryRange（单列）、seriesRange（同样行数，最多8列，pie仅1列），可选 title/seriesName/seriesNames；aggregate 可为 none/count/sum/avg，分组时数值仅1列，count可省略seriesRange。"
        +"图表沿用旧展示口径：空或非数值按0，分组空分类略过，avg四舍五入两位；需要其他业务口径先提问。只读步骤使用 tool_success 和 step_succeeded，不得把读取结果作为写入验证或伪装 apply_actions。";
    private ReadDisplayTools() { }
    public static void checkRunContext(JsonNode plan,JsonNode run){for(JsonNode step:plan.path("steps"))if("read_display".equals(step.path("tool").asText())&&"getSelection".equals(step.path("inputBindings").path("type").asText()))require(run.path("readSelection").isObject()&&run.path("readSelection").path("sheetId").asText().equals(step.path("inputBindings").path("sheetId").asText()),"READ_SELECTION_REQUIRED: 计划缺少该Sheet的启动选区");}
    public static void admit(JsonNode snapshot,JsonNode args){if("getSelection".equals(args.path("type").asText())){fields(args,"type","sheetId");AgentTools.sheet(snapshot,text(args,"sheetId"));}else execute(snapshot,obj(),args);}
    private static void fields(JsonNode n,String... allowed){Set<String> keys=new HashSet<>(Arrays.asList(allowed));require(n.isObject(),"READ_DISPLAY_INVALID: 参数必须为对象");n.fieldNames().forEachRemaining(k->require(keys.contains(k),"READ_DISPLAY_INVALID: 未注册字段 "+k));}
    private static int integer(JsonNode n,int min,int max){require(n.isIntegralNumber()&&n.canConvertToInt()&&n.intValue()>=min&&n.intValue()<=max,"READ_DISPLAY_INVALID: 索引或尺寸无效");return n.intValue();}
    private static String label(JsonNode n,String fallback){if(n.isMissingNode())return fallback;require(n.isTextual()&&n.asText().length()<=200,"READ_DISPLAY_INVALID: 文本无效或过长");return n.asText();}
    private static int[] selectionBounds(JsonNode sheet,String a1){int[] r=AgentTools.range(a1);require(r[2]<sheet.path("rowCount").asInt()&&r[3]<sheet.path("columnCount").asInt(),"READ_DISPLAY_INVALID: 选区越界");return r;}
    private static int[] bounds(JsonNode sheet,String a1){int[] r=selectionBounds(sheet,a1);require((long)(r[2]-r[0]+1)*(r[3]-r[1]+1)<=1000,"READ_DISPLAY_BUDGET: 超过1000格物化预算");return r;}
    private static JsonNode scalar(JsonNode sheet,int row,int col){JsonNode v=AgentTools.cell(sheet,row,col).path("v");require(v.isMissingNode()||v.isNull()||v.isValueNode()&&(!v.isNumber()||Double.isFinite(v.asDouble())),"READ_DISPLAY_INVALID: 非标量或非有限值");return v.isMissingNode()?NullNode.instance:v.deepCopy();}
    private static ArrayNode grid(JsonNode sheet,int[] r,boolean formulas){ArrayNode out=arr();for(int row=r[0];row<=r[2];row++){ArrayNode line=arr();for(int col=r[1];col<=r[3];col++){if(formulas){JsonNode cell=AgentTools.cell(sheet,row,col);require(!cell.hasNonNull("si")&&(!cell.hasNonNull("f")||cell.path("f").isTextual()),"READ_DISPLAY_INVALID: 共享或非文本公式尚未展开");line.add(cell.path("f").asText(""));}else line.add(scalar(sheet,row,col));}out.add(line);}return out;}
    private static String a1(int row,int col){String s="";for(int c=col+1;c>0;c=(c-1)/26)s=(char)('A'+(c-1)%26)+s;return s+(row+1);}
    private static String a1(int[] r){String first=a1(r[0],r[1]),last=a1(r[2],r[3]);return first.equals(last)?first:first+":"+last;}
    private static int[] rectangle(JsonNode n,JsonNode sheet){require(n.isObject(),"READ_DISPLAY_INVALID: 区域元数据缺失");int rows=integer(sheet.path("rowCount"),1,1000000),cols=integer(sheet.path("columnCount"),1,16384);int[] r={integer(n.path("startRow"),0,rows-1),integer(n.path("startColumn"),0,cols-1),integer(n.path("endRow"),0,rows-1),integer(n.path("endColumn"),0,cols-1)};require(r[0]<=r[2]&&r[1]<=r[3],"READ_DISPLAY_INVALID: 区域次序无效");return r;}
    /** UI selection is client-declared navigation context, never write authorization. */
    public static ObjectNode selection(JsonNode supplied,JsonNode snapshot,String activeSheet){
        fields(supplied,"sheetId","range","activeCell");String id=text(supplied,"sheetId");require(id.equals(activeSheet),"READ_SELECTION_INVALID: 捕获的活动Sheet已变化");JsonNode sheet=AgentTools.sheet(snapshot,id);int[] r=selectionBounds(sheet,text(supplied,"range"));ObjectNode out=obj().put("sheetId",id).put("range",a1(r));
        JsonNode cell=supplied.path("activeCell");if(!cell.isMissingNode()&&!cell.isNull()){fields(cell,"row","column");int row=integer(cell.path("row"),r[0],r[2]),col=integer(cell.path("column"),r[1],r[3]);out.set("activeCell",obj().put("row",row).put("column",col).put("a1",a1(row,col)));}else out.putNull("activeCell");return out;
    }
    public static ObjectNode execute(JsonNode snapshot,JsonNode run,JsonNode args){
        String type=text(args,"type"),id=text(args,"sheetId");require(TYPES.contains(type),"READ_DISPLAY_INVALID: 非只读动作");JsonNode sheet=AgentTools.sheet(snapshot,id);ObjectNode result=obj();
        if(Arrays.asList("getRangeValue","getRangeFormulas").contains(type)){fields(args,"type","sheetId","range");int[] r=bounds(sheet,text(args,"range"));result.put("a1",a1(r));result.set("getRangeValue".equals(type)?"values":"formulas",grid(sheet,r,"getRangeFormulas".equals(type)));}
        else if("getMerges".equals(type)){fields(args,"type","sheetId");JsonNode merges=sheet.path("mergeData");require(merges.isMissingNode()||merges.isArray()&&merges.size()<=1000,"READ_DISPLAY_BUDGET: 合并元数据无效或超限");ArrayNode list=arr();for(JsonNode m:merges){int[] r=rectangle(m,sheet);list.add(obj().put("startRow",r[0]).put("endRow",r[2]).put("startColumn",r[1]).put("endColumn",r[3]).put("a1",a1(r)));}result.set("merges",list);}
        else if("getSelection".equals(type)){fields(args,"type","sheetId");JsonNode selected=run.path("readSelection");require(selected.isObject()&&id.equals(selected.path("sheetId").asText()),"READ_SELECTION_REQUIRED: 没有该Sheet的启动选区，不能推测");int[] r=selectionBounds(sheet,text(selected,"range"));result.set("selection",obj().put("a1",a1(r)).put("startRow",r[0]).put("endRow",r[2]).put("startColumn",r[1]).put("endColumn",r[3]));result.set("activeCell",selected.path("activeCell").deepCopy());result.put("capturedAtStart",true);}
        else if("getFilter".equals(type)){fields(args,"type","sheetId");result=filter(snapshot,sheet,id);}
        else {result=chart(sheet,args);}
        ObjectNode out=obj().put("type",type).put("sheetId",id);out.set("result",result);require(out.toString().length()<=200000,"READ_DISPLAY_BUDGET: 结果超过20万字符");return out;
    }
    private static ObjectNode filter(JsonNode snapshot,JsonNode sheet,String id){
        JsonNode found=null;for(JsonNode resource:snapshot.path("resources"))if("SHEET_FILTER_PLUGIN".equals(resource.path("name").asText())){require(found==null,"READ_DISPLAY_INVALID: 重复筛选资源");require(resource.path("data").isTextual(),"READ_DISPLAY_INVALID: 筛选资源不是JSON文本");String raw=resource.path("data").asText();found=raw.trim().isEmpty()?obj():parse(raw);require(found.isObject(),"READ_DISPLAY_INVALID: 筛选资源无效");}
        JsonNode f=found==null?obj():found.path(id);ObjectNode out=obj().put("hasFilter",!f.isMissingNode()&&!f.isNull()&&f.size()>0);out.putNull("range");out.set("columns",arr());out.set("filteredOutRows",arr());if(!out.path("hasFilter").asBoolean())return out;
        int[] r=rectangle(f.path("ref"),sheet);out.put("range",a1(r));JsonNode columns=f.path("filterColumns"),rows=f.path("cachedFilteredOut");require((columns.isMissingNode()||columns.isArray()&&columns.size()<=1000)&&(rows.isMissingNode()||rows.isArray()&&rows.size()<=1000),"READ_DISPLAY_BUDGET: 筛选元数据无效或超限");
        ArrayNode list=arr();for(JsonNode c:columns){int col=integer(c.path("colId"),r[1],r[3]);list.add(obj().put("column",col).set("criteria",c.deepCopy()));}out.set("columns",list);ArrayNode hidden=arr();for(JsonNode row:rows)hidden.add(integer(row,r[0]+1,r[2]));out.set("filteredOutRows",hidden);return out;
    }
    private static String cellText(JsonNode v,boolean grouping){if(v.isNull())return grouping?"":"null";return grouping?v.asText().trim():v.asText();}
    private static double numeric(JsonNode v){if(v.isNull()||v.asText().trim().isEmpty())return 0;if(v.isBoolean())return v.asBoolean()?1:0;double n;try{n=Double.parseDouble(v.asText().trim());}catch(NumberFormatException ignored){return 0;}if(Double.isNaN(n))return 0;require(Double.isFinite(n),"READ_DISPLAY_INVALID: 图表非有限值");return n;}
    private static ObjectNode chart(JsonNode sheet,JsonNode a){
        fields(a,"type","sheetId","chartType","categoryRange","seriesRange","seriesName","seriesNames","title","aggregate");String type=text(a,"chartType"),aggregate=label(a.path("aggregate"),"none"),title=label(a.path("title"),"");require(Arrays.asList("bar","line","pie").contains(type)&&Arrays.asList("none","count","sum","avg").contains(aggregate),"READ_DISPLAY_INVALID: 图表类型或聚合无效");int[] cr=bounds(sheet,text(a,"categoryRange"));require(cr[1]==cr[3],"READ_DISPLAY_INVALID: 分类必须为单列");
        int[] sr=null;if(a.has("seriesRange")){sr=bounds(sheet,text(a,"seriesRange"));require(sr[2]-sr[0]==cr[2]-cr[0]&&sr[3]-sr[1]<8,"READ_DISPLAY_INVALID: 图表行数或系列数不匹配");}require(sr!=null||"count".equals(aggregate),"READ_DISPLAY_INVALID: 缺少数值区域");boolean grouped=!"none".equals(aggregate);if(grouped||"pie".equals(type))require(sr==null||sr[1]==sr[3],"READ_DISPLAY_INVALID: 分组/饼图只接受单数值列");int total=(cr[2]-cr[0]+1)+(sr==null?0:(sr[2]-sr[0]+1)*(sr[3]-sr[1]+1));require(total<=1000,"READ_DISPLAY_BUDGET: 图表来源合计超过1000格");
        ArrayNode names=arr(),series=arr();List<List<Double>> data=new ArrayList<>();
        if(grouped){LinkedHashMap<String,double[]> groups=new LinkedHashMap<>();for(int i=0;i<=cr[2]-cr[0];i++){String key=cellText(scalar(sheet,cr[0]+i,cr[1]),true);if(key.isEmpty())continue;double[] g=groups.computeIfAbsent(key,k->new double[2]);g[0]++;if(sr!=null)g[1]+=numeric(scalar(sheet,sr[0]+i,sr[1]));require(Double.isFinite(g[1]),"READ_DISPLAY_INVALID: 聚合超出有限范围");}List<Double> values=new ArrayList<>();for(Map.Entry<String,double[]> g:groups.entrySet()){names.add(g.getKey());double[] n=g.getValue();values.add("count".equals(aggregate)?n[0]:"sum".equals(aggregate)?n[1]:Math.floor(n[1]/n[0]*100.0+0.5)/100.0);}data.add(values);}
        else {for(int i=cr[0];i<=cr[2];i++)names.add(cellText(scalar(sheet,i,cr[1]),false));for(int col=sr[1];col<=sr[3];col++){List<Double> values=new ArrayList<>();for(int row=sr[0];row<=sr[2];row++)values.add(numeric(scalar(sheet,row,col)));data.add(values);}}
        JsonNode supplied=a.path("seriesNames");require(supplied.isMissingNode()||supplied.isArray()&&supplied.size()<=8,"READ_DISPLAY_INVALID: 系列名称无效");String single=label(a.path("seriesName"),"");
        for(int i=0;i<data.size();i++){String fallback=grouped?("count".equals(aggregate)?"数量":"sum".equals(aggregate)?"合计":"平均值"):data.size()>1?"系列"+(i+1):"数值";String name=grouped?(single.isEmpty()?fallback:single):label(supplied.path(i),single.isEmpty()?fallback:single);ObjectNode s=obj().put("type",type);if(!"pie".equals(type)||grouped)s.put("name",name);ArrayNode values=arr();for(int row=0;row<data.get(i).size();row++){double n=data.get(i).get(row);require(Double.isFinite(n),"READ_DISPLAY_INVALID: 图表结果非有限值");if("pie".equals(type))values.add(obj().put("name",names.get(row).asText()).put("value",n));else values.add(n);}s.set("data",values);if("pie".equals(type))s.put("radius","60%");series.add(s);}
        ObjectNode option=obj();option.set("title",obj().put("text",title).put("left","center"));option.set("tooltip",obj().put("trigger","pie".equals(type)?"item":"axis"));option.set("series",series);
        if("pie".equals(type))option.set("legend",obj().put("orient","vertical").put("left","left"));else {option.set("grid",obj().put("left","3%").put("right","4%").put("bottom","3%").put("containLabel",true));option.set("xAxis",obj().put("type","category").set("data",names));option.set("yAxis",obj().put("type","value"));if(series.size()>1)option.set("legend",obj().put("bottom",0));}
        ObjectNode result=obj().put("chartType",type).put("title",title).put("categoryRange",text(a,"categoryRange"));if(a.has("seriesRange"))result.put("seriesRange",text(a,"seriesRange"));result.set("chartOption",option);return result;
    }
}
